using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Reflection;using System.Text;
namespace FortsStudio {
 public static class FortsRange {
  static string N(double n){return n.ToString("0.######",CultureInfo.InvariantCulture);}static string Q(string s){return Exporter.Q(s);}
  public static string MapName(Project p){return "FMS_Range_"+p.Id.Substring(0,12);}
  public static string ModName(Project p){return "fms_range_"+p.Id.Substring(0,12);}
  static string NodeKey(float x,float y){return N(x)+":"+N(y);}
  public static List<string> Issues(Project p){var result=new List<string>();if(p.Scene.Count==0)result.Add("Добавьте балки на площадку.");if(p.Scene.Count>350)result.Add("Для полигона допускается до 350 балок.");foreach(int team in new[]{1,2}){var links=p.Scene.Where(x=>x.Team==team).ToList();if(links.Count==0)continue;var seen=new HashSet<string>{NodeKey(links[0].X1,links[0].Y1)};bool changed=true;while(changed){changed=false;foreach(var l in links){string a=NodeKey(l.X1,l.Y1),b=NodeKey(l.X2,l.Y2);if(seen.Contains(a)||seen.Contains(b)){if(seen.Add(a))changed=true;if(seen.Add(b))changed=true;}}}if(links.Any(x=>!seen.Contains(NodeKey(x.X1,x.Y1))))result.Add("У стороны "+team+" несколько отдельных конструкций. Соедините их балками или назначьте цели другую сторону.");}
   foreach(var link in p.Scene){var material=p.Entities.FirstOrDefault(x=>x.Kind=="materials"&&x.Key==link.Material);if(material==null){var t=Catalog.Templates.FirstOrDefault(x=>x.Kind=="materials"&&x.Key==link.Material);if(t!=null)material=Catalog.Create(t.Kind,t.Key,p.GameRoot);}if(material==null){result.Add("Не найден материал: "+link.Material);continue;}double length=Math.Sqrt(Math.Pow(link.X2-link.X1,2)+Math.Pow(link.Y2-link.Y1,2))*p.Preview.GridUnits;if(length<material.V("MinLength",37.5)-.01||length>material.V("MaxLinkLength",218)+.01)result.Add("Балка "+material.NameRu+": длина "+N(length)+" вне диапазона строительства.");}
   foreach(var item in p.Placed){if(Platform(p,item)==null)result.Add("Объект "+item.Entity+" не стоит на горизонтальной балке.");}return result.Distinct().ToList();}
  static Segment Platform(Project p,PlacedItem obj){return p.Scene.FirstOrDefault(x=>Math.Abs(x.Y1-x.Y2)<.01&&Math.Abs(obj.Y-x.Y1)<.05&&obj.X>Math.Min(x.X1,x.X2)&&obj.X<Math.Max(x.X1,x.X2));}
  static string Config(Project p){var sb=new StringBuilder("local range_map = "+Q(MapName(p))+"\nlocal range_tag = "+Q("FMS_RANGE_"+p.Id.Substring(0,12))+"\nlocal range_nodes = {\n");var points=new List<string>();foreach(var l in p.Scene)foreach(var pt in new[]{new[]{l.X1,l.Y1},new[]{l.X2,l.Y2}}){string key=l.Team+":"+NodeKey(pt[0],pt[1]);if(points.Contains(key))continue;points.Add(key);sb.Append("{x="+N(pt[0])+",y="+N(pt[1])+",team="+l.Team+"},\n");}sb.Append("}\nlocal range_links = {\n");foreach(var l in p.Scene.OrderBy(x=>Math.Pow(x.X2-x.X1,2)+Math.Pow(x.Y2-x.Y1,2)))sb.Append("{a="+(points.IndexOf(l.Team+":"+NodeKey(l.X1,l.Y1))+1)+",b="+(points.IndexOf(l.Team+":"+NodeKey(l.X2,l.Y2))+1)+",material="+Q(l.Material)+",team="+l.Team+"},\n");sb.Append("}\nlocal range_devices = {\n");foreach(var obj in p.Placed){var l=Platform(p,obj);if(l==null)continue;float ax=Math.Min(l.X1,l.X2),bx=Math.Max(l.X1,l.X2);sb.Append("{a="+(points.IndexOf(l.Team+":"+NodeKey(ax,l.Y1))+1)+",b="+(points.IndexOf(l.Team+":"+NodeKey(bx,l.Y1))+1)+",t="+N((obj.X-ax)/(bx-ax))+",name="+Q(obj.Entity)+",team="+l.Team+"},\n");}sb.Append("}\nlocal range_unit = "+N(p.Preview.GridUnits)+"\nlocal range_grounded = "+(p.Preview.RangeGrounded?"true":"false")+"\nlocal range_timeout = "+N(Math.Max(90,p.Scene.Count*12+p.Placed.Count*20))+"\n");using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("FortsStudio.range.lua"))using(var reader=new StreamReader(stream))sb.Append(reader.ReadToEnd());return sb.ToString();}
  public static string Prepare(Project project,string parent,bool install){if(!System.Text.RegularExpressions.Regex.IsMatch(project.Id??"",@"^[a-fA-F0-9]{32}$"))throw new Exception("Неверный идентификатор проекта.");var issues=Issues(project);if(issues.Count>0)throw new Exception(String.Join("\n",issues));var copy=Storage.Json().Deserialize<Project>(Storage.Json().Serialize(project));copy.Folder=ModName(project);copy.NameRu="Полигон · "+project.NameRu;copy.NameEn="Range · "+project.NameEn;string built=Exporter.Build(copy,Path.Combine(parent,"mods"));string script=Path.Combine(built,"script.lua");File.AppendAllText(script,"\n"+Config(project),Encoding.Unicode);
   string map=Path.Combine(parent,"maps",MapName(project));Directory.CreateDirectory(map);string template=Path.Combine(project.GameRoot,"data","maps","-template-");foreach(string ext in new[]{".fwe",".spr"})File.Copy(Path.Combine(template,"-template-"+ext),Path.Combine(map,MapName(project)+ext));File.WriteAllText(Path.Combine(map,".fms-owned"),project.Id);string meta="Mods = { "+Q(copy.Folder)+" }\nSandbox = true\nSkirmish = true\nMultiplayer = false\nAllowEdit = true\nSymmetrical = false\nAuthor = L\"Forts Mod Studio\"\nDescLine1 = L\"Native Forts physics. Studio scene attached to an elevated joint.\"\nDescLine2 = L\"Sandbox: aim and fire manually; restart to restore the scene.\"\n";File.WriteAllText(Path.Combine(map,MapName(project)+".lua"),meta,Encoding.Unicode);File.WriteAllText(Path.Combine(map,"displayname.lua"),"DisplayName = { English = L"+Q("FMS Range · "+project.NameEn)+", Russian = L"+Q("Полигон FMS · "+project.NameRu)+" }\n",Encoding.Unicode);File.Copy(Path.Combine(built,"preview.jpg"),Path.Combine(map,"preview-"+MapName(project)+"-1.jpg"));
   var errors=Exporter.Parse(built,project.GameRoot).Concat(Exporter.Parse(map,project.GameRoot)).ToArray();if(errors.Length>0)throw new Exception(String.Join("\n",errors));File.WriteAllText(Path.Combine(parent,"START.txt"),"Forts → Sandbox → Player maps → FMS Range / Полигон FMS.\r\nMap folder: "+MapName(project)+"\r\nOnly the range mod is required. Restart Forts after rebuilding.\r\n",Encoding.UTF8);if(install){InstallOwned(built,Path.Combine(project.GameRoot,"data","mods"),copy.Folder,project.Id);InstallOwned(map,Path.Combine(project.GameRoot,"data","maps"),MapName(project),project.Id);return Path.Combine(project.GameRoot,"data","maps",MapName(project));}return map;
  }
  static void InstallOwned(string built,string parent,string name,string id){string root=Path.GetFullPath(parent)+Path.DirectorySeparatorChar,dest=Path.GetFullPath(Path.Combine(parent,name));if(!dest.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("Неверный путь полигона.");if(Directory.Exists(dest)){string marker=Path.Combine(dest,".fms-owned");if(!File.Exists(marker)||File.ReadAllText(marker)!=id)throw new Exception("Папка полигона принадлежит другому проекту: "+dest);string backup=Path.GetFullPath(Path.Combine(parent,".fms-history",name+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")));if(!backup.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("Неверный путь резервной копии.");Directory.CreateDirectory(Path.GetDirectoryName(backup));Directory.Move(dest,backup);}Exporter.CopyTree(built,dest);}
  public static string Report(Project p){string users=Path.Combine(p.GameRoot,"users");if(!Directory.Exists(users))return "Журнал игры не найден.";var file=Directory.GetFiles(users,"log.txt",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTime).FirstOrDefault();if(file==null)return "Журнал игры пока не создан.";string tag="FMS_RANGE_"+p.Id.Substring(0,12);var entries=File.ReadAllLines(file).Where(x=>x.Contains(tag)).Reverse().Take(70).Reverse();return String.Join("\r\n",entries.DefaultIfEmpty("Этот полигон ещё не отмечен в текущем журнале Forts."));}
 }
}
